<?php declare(strict_types=1);require_once __DIR__.'/includes/auth.php';$merchant=require_login();$pageTitle='Payment Links';$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim((string)($_POST['title']??''));$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);$days=(int)($_POST['expiry_days']??0);$redirect=trim((string)($_POST['redirect_url']??''));if($title===''||$amount===false||$amount<1||$amount>1000000||!in_array($days,[0,1,7,30],true)||!valid_http_url($redirect)){$message='Enter a title and a valid amount.';}else{$slug=bin2hex(random_bytes(9));$expires=$days>0?date('Y-m-d H:i:s',time()+$days*86400):null;$q=db()->prepare('INSERT INTO payment_links(merchant_id,slug,title,amount,description,redirect_url,expires_at) VALUES(?,?,?,?,?,?,?)');$q->execute([$merchant['id'],$slug,substr($title,0,160),number_format($amount,2,'.',''),substr((string)($_POST['description']??''),0,1500),$redirect?:null,$expires]);$message='Payment link created.';}}$q=db()->prepare('SELECT slug,title,amount,description,expires_at,created_at FROM payment_links WHERE merchant_id=? ORDER BY created_at DESC LIMIT 100');$q->execute([$merchant['id']]);$links=$q->fetchAll();require __DIR__.'/includes/dashboard-header.php';?>
<div class="page-title-row" style="margin-bottom:24px"><div><h1>Payment links</h1><p>Create shareable hosted checkout links with a fixed amount.</p></div></div><?php if($message):?><div class="note panel"><?=h($message)?></div><?php endif?><div class="dashboard-bottom-grid"><div class="card"><div class="card-title"><h3>Create a payment link</h3></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><div class="field"><label>Link title</label><input name="title" placeholder="e.g. Design consultation" required></div><div class="field"><label>Amount (INR)</label><input type="number" min="1" step="0.01" name="amount" placeholder="499.00" required></div><div class="field"><label>Expiry</label><select name="expiry_days"><option value="0">No expiry</option><option value="1">1 day</option><option value="7">7 days</option><option value="30">30 days</option></select></div><div class="field full"><label>Post-payment redirect URL (optional, HTTPS)</label><input type="url" name="redirect_url" placeholder="https://your-site.example/thank-you"></div><div class="field full"><label>Description</label><textarea name="description" rows="3" placeholder="Optional details shown to your customer"></textarea></div><div class="field full"><button class="btn btn-primary">Create link →</button></div></form></div><div class="card"><div class="card-title"><h3>Share links</h3><span style="font-size:10px;color:var(--muted)"><?=count($links)?> total</span></div><?php if(!$links):?><p style="font-size:11px;color:var(--muted)">Links you create will appear here.</p><?php endif?><?php foreach($links as $l):$url=rtrim((string)envv('APP_URL','https://tggateways.in'),'/').'/pay.php?link='.$l['slug'];?><div style="padding:13px 0;border-bottom:1px solid var(--line)"><strong style="font-size:11px"><?=h($l['title'])?></strong><span style="float:right;font-weight:600">₹<?=number_format((float)$l['amount'],2)?></span><div style="font-size:9px;color:#8692a5;margin:6px 0"><?=h($url)?></div><button class="btn btn-secondary" style="padding:6px 10px;font-size:9px" data-copy-value="<?=h($url)?>" onclick="navigator.clipboard.writeText(this.dataset.copyValue);this.textContent='Copied!'">Copy link</button></div><?php endforeach?></div></div><?php require __DIR__.'/includes/dashboard-footer.php';?>